/// <summary>
/// Runs the purge of old sales order API trace records, from the trace log form or as a batch job.
/// </summary>
public class DYLO_SalesOrderApiPurgeController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(
        classStr(DYLO_SalesOrderApiPurgeService),
        methodStr(DYLO_SalesOrderApiPurgeService, purge),
        SysOperationExecutionMode::Synchronous);
}

public static DYLO_SalesOrderApiPurgeController construct()
{
    return new DYLO_SalesOrderApiPurgeController();
}

public static void main(Args _args)
{
    DYLO_SalesOrderApiPurgeController controller = DYLO_SalesOrderApiPurgeController::construct();

    controller.parmArgs(_args);
    controller.startOperation();

    if (_args && _args.record() && FormDataUtil::isFormDataSource(_args.record()))
    {
        FormDataUtil::getFormDataSource(_args.record()).research();
    }
}
